package services

import (
	"context"
	"fmt"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/maoxiaoyue/hypgo/pkg/errors"
	"github.com/maoxiaoyue/hypgo/pkg/hidb"
	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"github.com/uptrace/bun"

	"legagent/app/models"
	"legagent/internal/moj"
)

// 法規資料庫（laws）錯誤目錄，代碼區段 E5xxx。
var (
	// ErrLawsInvalidSource 為來源資料不可用，例如法規代碼格式不符或代碼重複。
	//
	// @ai:generated by=claude-opus-5-5 date=2026-11-05
	ErrLawsInvalidSource = errors.Define("E5001", 422, "Law source data is invalid", "laws")
	// ErrLawsImportFailed 為寫入資料庫失敗；已完成的法規會保留，重新執行可補齊。
	//
	// @ai:generated by=claude-opus-5-5 date=2026-11-05
	ErrLawsImportFailed = errors.Define("E5002", 500, "Law import failed", "laws")
)

const (
	lawsSchema = "laws"
	// lawImportWorkers 限制同時寫入的法規數，避免佔滿共用資料庫的連線。
	lawImportWorkers = 8
)

var rePCode = regexp.MustCompile(`^[A-Z0-9]{8}$`)

// LawsService 把法規寫入 PostgreSQL，每部法規一張表。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 集中管理 laws schema，呼叫端不必知道表名規則
type LawsService struct {
	db  *hidb.Database
	log *logger.Logger
}

// NewLawsService 建立服務。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 以建構子注入資料庫，讓業務邏輯不綁定連線建立方式
// @ai:input db 資料庫, log
// @ai:output *LawsService
// @ai:sideeffect none
func NewLawsService(db *hidb.Database, log *logger.Logger) *LawsService {
	return &LawsService{db: db, log: log}
}

// LawTableName 回傳法規的表名（不含 schema），並拒絕不符格式的代碼。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 表名來自外部資料，必須先驗證才能組進 DDL，也避免中文名稱超過識別字長度
// @ai:input pcode 法規代碼
// @ai:output 表名，例如 law_b0000001；格式不符時回傳 error
// @ai:sideeffect none
func LawTableName(pcode string) (string, error) {
	if !rePCode.MatchString(pcode) {
		return "", fmt.Errorf("invalid pcode %q", pcode)
	}
	return "law_" + strings.ToLower(pcode), nil
}

// BuildLawRows 把一部法規轉成目錄列與條文列。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 轉換邏輯與資料庫分離，不連資料庫也能測試
// @ai:input law 解析後的法規
// @ai:output 目錄列、條文列、error（代碼不合法）
// @ai:sideeffect none
func BuildLawRows(law moj.Law) (models.LawCatalog, []models.LawArticleRow, error) {
	table, err := LawTableName(law.PCode)
	if err != nil {
		return models.LawCatalog{}, nil, err
	}
	rows := make([]models.LawArticleRow, 0, len(law.Articles))
	for i, a := range law.Articles {
		rows = append(rows, models.LawArticleRow{
			Seq: i + 1, ArticleNo: a.No, Label: a.Label, Chapter: a.Chapter, Content: a.Content,
		})
	}
	return models.LawCatalog{
		PCode: law.PCode, TableName: lawsSchema + "." + table, Name: law.Name, Nature: string(law.Nature),
		Category: law.Category, Repealed: law.Repealed, UpdatedOn: law.UpdatedAt, EffectiveOn: law.Effective,
		EnglishName: law.EnglishName, History: law.History, Preamble: law.Preamble,
		SourceURL: law.SourceURL, ArticleCount: len(rows),
	}, rows, nil
}

// Import 建立 laws schema 與目錄表，再逐部法規建表寫入；可重複執行，條文會以來源資料覆蓋。
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 每部法規各用一個交易，因為上萬張表放在同一交易會超過 max_locks_per_transaction
// @ai:input ctx, laws 解析後的全部法規（代碼不得重複）
// @ai:output *models.LawImportStats, error（ErrLawsInvalidSource / ErrLawsImportFailed）
// @ai:sideeffect 建立 laws schema 與資料表、覆寫各法規表內容
func (s *LawsService) Import(ctx context.Context, laws []moj.Law) (*models.LawImportStats, error) {
	seen := make(map[string]bool, len(laws))
	for _, law := range laws {
		if _, err := LawTableName(law.PCode); err != nil {
			s.log.Error("invalid law source", "name", law.Name, "err", err)
			return nil, ErrLawsInvalidSource.With("name", law.Name).With("reason", err.Error())
		}
		if seen[law.PCode] {
			s.log.Error("duplicate pcode in source", "pcode", law.PCode)
			return nil, ErrLawsInvalidSource.With("pcode", law.PCode).With("reason", "duplicate pcode")
		}
		seen[law.PCode] = true
	}

	writer := s.db.WriteHypDB()
	if _, err := writer.NewRaw("CREATE SCHEMA IF NOT EXISTS ?", bun.Ident(lawsSchema)).Exec(ctx); err != nil {
		s.log.Error("create laws schema failed", "err", err)
		return nil, ErrLawsImportFailed.With("reason", err.Error())
	}
	if _, err := writer.NewCreateTable().Model((*models.LawCatalog)(nil)).IfNotExists().Exec(ctx); err != nil {
		s.log.Error("create laws catalog failed", "err", err)
		return nil, ErrLawsImportFailed.With("reason", err.Error())
	}
	// 觸發器函式在開 worker 前建好；並行重建同一個函式會互相衝突。
	err := ensureStampFunction(ctx, writer)
	if err == nil {
		err = ensureRowStamps(ctx, writer, lawsSchema, "catalog")
	}
	if err != nil {
		s.log.Error("prepare row stamps failed", "err", err)
		return nil, ErrLawsImportFailed.With("reason", err.Error())
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	jobs := make(chan moj.Law)
	var (
		wg       sync.WaitGroup
		once     sync.Once
		firstErr error
		done     atomic.Int64
	)
	for range lawImportWorkers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for law := range jobs {
				if err := s.importOne(workCtx, law); err != nil {
					once.Do(func() {
						firstErr = fmt.Errorf("%s %s: %w", law.PCode, law.Name, err)
						cancel()
					})
					continue
				}
				if n := done.Add(1); n%1000 == 0 {
					s.log.Info("importing laws", "done", n, "total", len(laws))
				}
			}
		}()
	}
send:
	for _, law := range laws {
		select {
		case jobs <- law:
		case <-workCtx.Done():
			break send
		}
	}
	close(jobs)
	wg.Wait()

	if firstErr == nil {
		firstErr = ctx.Err()
	}
	if firstErr != nil {
		s.log.Error("import laws failed", "done", done.Load(), "total", len(laws), "err", firstErr)
		return nil, ErrLawsImportFailed.With("done", done.Load()).With("reason", firstErr.Error())
	}

	stats := &models.LawImportStats{}
	err = writer.NewSelect().Model((*models.LawCatalog)(nil)).
		ColumnExpr("count(*)").
		ColumnExpr("count(*) FILTER (WHERE repealed)").
		ColumnExpr("coalesce(sum(article_count), 0)").
		Scan(ctx, &stats.Laws, &stats.Repealed, &stats.Articles)
	if err != nil {
		s.log.Error("count laws failed", "err", err)
		return nil, ErrLawsImportFailed.With("reason", err.Error())
	}
	return stats, nil
}

// importOne 在單一交易內建立並填滿一部法規的表，失敗時這部法規維持原狀。
func (s *LawsService) importOne(ctx context.Context, law moj.Law) error {
	catalog, rows, err := BuildLawRows(law)
	if err != nil {
		return err
	}
	schema, table := bun.Ident(lawsSchema), bun.Ident(strings.TrimPrefix(catalog.TableName, lawsSchema+"."))
	return s.db.HypDBTransaction(ctx, func(ctx context.Context, tx bun.Tx) error {
		if _, err := tx.NewRaw(`CREATE TABLE IF NOT EXISTS ?.? (
			seq integer PRIMARY KEY,
			article_no text NOT NULL,
			label text NOT NULL,
			chapter text NOT NULL,
			content text NOT NULL
		)`, schema, table).Exec(ctx); err != nil {
			return fmt.Errorf("create table: %w", err)
		}
		if _, err := tx.NewRaw("COMMENT ON TABLE ?.? IS ?", schema, table, law.Name).Exec(ctx); err != nil {
			return fmt.Errorf("comment table: %w", err)
		}
		if err := ensureRowStamps(ctx, tx, lawsSchema, strings.TrimPrefix(catalog.TableName, lawsSchema+".")); err != nil {
			return err
		}
		// 逐列 upsert 而不是清表重寫，未修正的條文才能保留 created_at，updated_at 也只標出真正改過的條文。
		if len(rows) > 0 {
			if _, err := tx.NewInsert().Model(&rows).ModelTableExpr("?.?", schema, table).
				On("CONFLICT (seq) DO UPDATE").
				Set("article_no = EXCLUDED.article_no, label = EXCLUDED.label").
				Set("chapter = EXCLUDED.chapter, content = EXCLUDED.content").
				Exec(ctx); err != nil {
				return fmt.Errorf("upsert articles: %w", err)
			}
		}
		// seq 從 1 連續編號，超出本次條數的是已刪除的條文。
		if _, err := tx.NewRaw("DELETE FROM ?.? WHERE seq > ?", schema, table, len(rows)).Exec(ctx); err != nil {
			return fmt.Errorf("delete removed articles: %w", err)
		}
		if _, err := tx.NewInsert().Model(&catalog).On("CONFLICT (pcode) DO UPDATE").
			Set("table_name = EXCLUDED.table_name, name = EXCLUDED.name, nature = EXCLUDED.nature").
			Set("category = EXCLUDED.category, repealed = EXCLUDED.repealed, updated_on = EXCLUDED.updated_on").
			Set("effective_on = EXCLUDED.effective_on, english_name = EXCLUDED.english_name").
			Set("history = EXCLUDED.history, preamble = EXCLUDED.preamble, source_url = EXCLUDED.source_url").
			Set("article_count = EXCLUDED.article_count").
			Exec(ctx); err != nil {
			return fmt.Errorf("upsert catalog: %w", err)
		}
		return nil
	})
}
